class Solution:
    def zeroTrios(self, ratings: List[int]) -> List[List[int]]:
        # Sort, fix first rating a[i], then squeeze lo and hi inward
        # Pair must sum to -a[i]; sum too small raises lo, too big lowers hi
        # Skipping repeated vals keeps trios distinct
        a = sorted(ratings)
        n, out = len(a), []
        for i in range(n - 2):
            # all three positive from here, so none sums to 0
            if a[i] > 0:
                break
            # repeat of first val, so its trios already found
            if i and a[i] == a[i - 1]:
                continue
            # pointers span everything right of i
            lo, hi = i + 1, n - 1
            while lo < hi:
                # trio sum
                total = a[i] + a[lo] + a[hi]
                if total < 0:
                    lo += 1
                elif total > 0:
                    hi -= 1
                else:
                    out.append([a[i], a[lo], a[hi]])
                    # step both, ensuring same trio isn't found again
                    lo += 1
                    hi -= 1
                    # skip repeat of a[lo]; repeat of a[hi] then sums too big
                    while lo < hi and a[lo] == a[lo - 1]:
                        lo += 1
        return out

