class Solution {
    public List<List<Integer>> zeroTrios(int[] ratings) {
        // Sort, fix first rating a[i], then squeeze lo and hi inward
        // Pair must sum to -a[i]; sum too small raises lo, too big lowers hi
        // Skipping repeated vals keeps trios distinct
        int[] a = ratings.clone();
        Arrays.sort(a);
        int n = a.length;
        List<List<Integer>> out = new ArrayList<>();
        // stop once first val > 0, as all three would be positive
        for (int i = 0; i < n - 2 && a[i] <= 0; i++) {
            // repeat of first val, so its trios already found
            if (i > 0 && a[i] == a[i - 1]) continue;
            // pointers span everything right of i
            int lo = i + 1, hi = n - 1;
            while (lo < hi) {
                // trio sum
                int total = a[i] + a[lo] + a[hi];
                if (total < 0) lo++;
                else if (total > 0) hi--;
                else {
                    out.add(List.of(a[i], a[lo], a[hi]));
                    // step both, ensuring same trio isn't found again
                    lo++;
                    hi--;
                    // skip repeat of a[lo]; repeat of a[hi] then sums too big
                    while (lo < hi && a[lo] == a[lo - 1]) lo++;
                }
            }
        }
        return out;
    }
}

