class Solution {
    public int[] mergeAll(int[][] lists) {
        // Min-heap holds front val of each gate's list
        // Pop smallest, then push next val from same gate
        // Smallest remaining val is some list's front, so pops come sorted
        // entries {val, gate, idx of val in gate}, smallest val first
        PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        // count of all vals, sizing out
        int total = 0;
        for (int gate = 0; gate < lists.length; gate++) {
            total += lists[gate].length;
            // empty gate has nothing to seed
            if (lists[gate].length > 0) heap.add(new int[]{lists[gate][0], gate, 0});
        }
        int[] out = new int[total];
        // slots of out filled so far
        int filled = 0;
        while (!heap.isEmpty()) {
            // smallest front val is next in merged order
            int[] top = heap.poll();
            out[filled++] = top[0];
            // next val from same gate takes its place
            int gate = top[1], idx = top[2] + 1;
            if (idx < lists[gate].length) heap.add(new int[]{lists[gate][idx], gate, idx});
        }
        return out;
    }
}

