        // Pop smallest, then push next val from same gate
        // Smallest remaining val is some list's front, so pops come sorted
        // entries (val, gate, idx in gate); greater<> makes min-heap
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> heap;
