        size_t total = 0;
        for (int gate = 0; gate < (int)lists.size(); gate++) {
            total += lists[gate].size();
            // empty gate has nothing to seed
            if (!lists[gate].empty()) heap.push({lists[gate][0], gate, 0});
        }
        vector<int> out;
        out.reserve(total);
        while (!heap.empty()) {
            // smallest front val is next in merged order
            auto [val, gate, idx] = heap.top();
            heap.pop();
            out.push_back(val);
            // next val from same gate takes its place
            if (idx + 1 < (int)lists[gate].size()) heap.push({lists[gate][idx + 1], gate, idx + 1});
        }
        return out;
    }
};

