class Solution {
    public int[] mergeAll(int[][] lists) {
        // Merge gate lists pairwise, round by round, until one remains
        // Each round halves list count, so about log k rounds
        // no gates, so empty result
        if (lists.length == 0) return new int[0];
        List<int[]> cur = new ArrayList<>(Arrays.asList(lists));
        // each round merges lists 0+1, 2+3, and so on
        while (cur.size() > 1) {
            List<int[]> next = new ArrayList<>();
            // step 2 walks pairs; odd one out carries over
            for (int k = 0; k < cur.size(); k += 2) {
                next.add(k + 1 < cur.size() ? merge(cur.get(k), cur.get(k + 1)) : cur.get(k));
            }
            cur = next;
        }
        return cur.get(0);
    }
    // two-pointer merge of two sorted lists
    private int[] merge(int[] a, int[] b) {
        int[] out = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        // smaller front val goes next
        while (i < a.length && j < b.length) out[k++] = a[i] <= b[j] ? a[i++] : b[j++];
        // one side ran out; rest of other is sorted, so append whole
        while (i < a.length) out[k++] = a[i++];
        while (j < b.length) out[k++] = b[j++];
        return out;
    }
}

