    vector<int> mergeAll(vector<vector<int>>& lists) {
        // Merge gate lists pairwise, round by round, until one remains
        // Each round halves list count, so about log k rounds
        // no gates, so empty result
        if (lists.empty()) return {};
        vector<vector<int>> cur = lists;
        // each round merges lists 0+1, 2+3, and so on
        while (cur.size() > 1) {
            vector<vector<int>> next;
            // step 2 walks pairs; odd one out carries over
            for (size_t k = 0; k < cur.size(); k += 2) {
                if (k + 1 < cur.size()) {
                    // two-pointer merge of two sorted lists
                    vector<int> merged(cur[k].size() + cur[k + 1].size());
                    merge(cur[k].begin(), cur[k].end(), cur[k + 1].begin(), cur[k + 1].end(), merged.begin());
                    next.push_back(move(merged));
                } else {
                    next.push_back(move(cur[k]));
                }
            }
            cur = move(next);
        }
        return cur[0];
    }
};

